<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { ElMessage } from 'element-plus';
import { Plus, Download } from 'lucide-vue-next';
import { api } from '../api';
import { useSessionStore } from '../stores/session';
import { saveBlob } from '../admission';
import QueryPanel from '../components/QueryPanel.vue';
import QueryField from '../components/QueryField.vue';
import CityAnalyticsDrawer from '../components/CityAnalyticsDrawer.vue';
import CityReportDocument from '../components/CityReportDocument.vue';
import { cityApi, day, draft, err, notifyDownload, text, time, useCityQuery } from '../city-analytics';
import '../city-analytics.css';
const session=useSessionStore(),canGenerate=computed(()=>session.user?.permissions.includes('analytics:report:generate')),canExport=computed(()=>session.user?.permissions.includes('analytics:report:export'));
const c=useCityQuery({q:'',category:'',reportType:'',generatedFrom:'',generatedTo:''});
const rows=ref<any[]>([]),total=ref(0),loading=ref(false),error=ref(''),detail=ref<any>(),detailLoading=ref(false),detailError=ref(''),options=ref<any>({enterprises:[]}),optionsError=ref(''),selected=ref<any[]>([]),createOpen=ref(false),createError=ref(''),saving=ref(false),exporting=ref(false);
const categories=[['OPERATIONS','运行统计'],['SAFETY','安全统计'],['COMPREHENSIVE','综合统计'],['ENTERPRISE','企业专项']],periods=[['DAILY','日报'],['WEEKLY','周报'],['MONTHLY','月报'],['QUARTERLY','季报'],['SPECIAL','自定义']];
const genRange=computed({get:()=>c.filters.generatedFrom&&c.filters.generatedTo?[c.filters.generatedFrom,c.filters.generatedTo]:[],set:(v:string[]|null)=>{c.filters.generatedFrom=v?.[0]??'';c.filters.generatedTo=v?.[1]??'';}});
const closedPeriod=(kind:string)=>{const today=day(new Date().toISOString()),d=new Date(today+'T00:00:00+08:00');if(kind==='DAILY'){const yesterday=day(new Date(+d-86400000).toISOString());return [yesterday,yesterday];}if(kind==='WEEKLY'){const weekday=new Date(+d+28800000).getUTCDay()||7;const end=new Date(+d-weekday*86400000);return [day(new Date(+end-6*86400000).toISOString()),day(end.toISOString())];}if(kind==='QUARTERLY'){const month=Number(today.slice(5,7)),q=Math.floor((month-1)/3)*3+1,first=new Date(`${today.slice(0,4)}-${String(q).padStart(2,'0')}-01T00:00:00+08:00`),end=new Date(+first-86400000),start=new Date(Date.UTC(Number(day(end.toISOString()).slice(0,4)),Math.floor((Number(day(end.toISOString()).slice(5,7))-1)/3)*3,1));return [day(start.toISOString()),day(end.toISOString())];}const last=day(new Date(+new Date(today.slice(0,7)+'-01T00:00:00+08:00')-86400000).toISOString());return [last.slice(0,7)+'-01',last];};
const d=draft(`wrc-city-report-${session.user?.id}`,{title:'',reportType:'MONTHLY',category:'COMPREHENSIVE',dates:closedPeriod('MONTHLY'),enterpriseId:''}),form=d.value;
const visible=computed({get:()=>!!c.id.value,set:v=>{if(!v)void c.close();}});let listId=0,detailId=0,lastSuggestion='';
function suggest(){if(form.title&&form.title!==lastSuggestion)return;lastSuggestion=`${session.user?.workspace?.cityName??''}无人车${categories.find(x=>x[0]===form.category)?.[1]??form.category}${text(form.reportType)}（${form.dates?.[0]??''}）`;form.title=lastSuggestion;}
function periodChanged(){if(form.reportType!=='SPECIAL')form.dates=closedPeriod(form.reportType);suggest();}
async function load(){const id=++listId;loading.value=true;error.value='';selected.value=[];try{const result=await api<any>(`${cityApi}/reports?${c.params()}`);if(id===listId){rows.value=result.items;total.value=result.total;if(!rows.value.length&&total.value&&c.page.value>1)void c.paginate(1);}}catch(e){if(id===listId)error.value=err(e);}finally{if(id===listId)loading.value=false;}}
async function loadOptions(){optionsError.value='';try{options.value=await api(`${cityApi}/options`);}catch(e){optionsError.value=err(e);}}
async function search(){const before=c.queryKey.value;await c.search();if(before===c.queryKey.value)await load();}
async function reset(){const before=c.queryKey.value;await c.reset();if(before===c.queryKey.value)await load();}
async function loadDetail(){const id=++detailId;detail.value=null;detailError.value='';if(!c.id.value)return;detailLoading.value=true;try{const result=await api(`${cityApi}/reports/${c.id.value}`);if(id===detailId)detail.value=result;}catch(e){if(id===detailId)detailError.value=err(e);}finally{if(id===detailId)detailLoading.value=false;}}
function openCreate(){suggest();createError.value='';createOpen.value=true;}
async function create(){if(!form.title.trim()||form.dates?.length!==2)return ElMessage.warning('请填写报表名称并选择统计周期');if(form.category==='ENTERPRISE'&&!form.enterpriseId)return ElMessage.warning('企业专项请选择企业');saving.value=true;createError.value='';try{const result=await api<any>(`${cityApi}/reports`,{method:'POST',body:JSON.stringify({title:form.title.trim(),reportType:form.reportType,category:form.category,from:form.dates[0],to:form.dates[1],enterpriseId:form.enterpriseId||undefined})});createOpen.value=false;d.clear();lastSuggestion='';await load();await c.open(result.id);ElMessage.success('报表已生成并留存，可预览后导出');}catch(e){createError.value=err(e);}finally{saving.value=false;}}
async function exportSelected(){if(!selected.value.length)return;if(selected.value.length>20)return ElMessage.warning('一次最多导出20份报表');exporting.value=true;try{const file=await api<any>(`${cityApi}/reports/batch-export`,{method:'POST',body:JSON.stringify({ids:selected.value.map(r=>r.id)})});const bytes=Uint8Array.from(atob(file.content),(c:string)=>c.charCodeAt(0));saveBlob(new Blob([bytes],{type:'application/zip'}),file.filename);}catch(e){ElMessage.error(err(e));}finally{exporting.value=false;}}
watch(c.queryKey,()=>void load(),{immediate:true});watch(c.id,()=>void loadDetail(),{immediate:true});watch(()=>form.category,suggest);void loadOptions();
</script>
<template><section class="ca-page ca-collection" :class="{'ca-has-detail':!!c.id.value}" :style="{'--ca-detail-width':'740px'}" aria-label="统计报表">
 <QueryPanel :loading="loading" @search="search" @reset="reset"><QueryField label="关键词" keyword><el-input v-model="c.filters.q" clearable placeholder="报表名称或编号" aria-label="关键词"/></QueryField><QueryField label="报表分类"><el-select v-model="c.filters.category" clearable placeholder="全部分类" aria-label="报表分类"><el-option v-for="[key,label] in categories" :key="key" :label="label" :value="key"/></el-select></QueryField><QueryField label="周期"><el-select v-model="c.filters.reportType" clearable placeholder="全部周期" aria-label="周期"><el-option v-for="[key,label] in periods" :key="key" :label="label" :value="key"/></el-select></QueryField><QueryField label="生成日期" wide><el-date-picker v-model="genRange" type="daterange" value-format="YYYY-MM-DD" range-separator="—" start-placeholder="开始日期" end-placeholder="结束日期" aria-label="生成日期"/></QueryField></QueryPanel>
 <div v-if="optionsError" class="ca-form-error" role="alert">{{optionsError}} <el-button link @click="loadOptions">重试</el-button></div>
 <article class="ca-card"><header class="ca-card-title"><h2>统计报表</h2><span class="ca-count">{{total}}</span><div class="ca-tools"><el-button v-if="canExport" :icon="Download" :disabled="!selected.length" :loading="exporting" @click="exportSelected">导出所选{{selected.length?`（${selected.length}）`:''}}</el-button><el-button v-if="canGenerate" type="primary" :icon="Plus" @click="openCreate">生成报表</el-button></div></header>
 <div v-if="error" class="ca-error" role="alert"><strong>报表列表暂时无法加载</strong><span>{{error}}</span><el-button @click="load">重试</el-button></div><div v-else class="ca-table" v-loading="loading"><el-table :data="rows" row-key="id" height="100%" :row-class-name="({row}:any)=>row.id===c.id.value?'ca-selected':''" empty-text="当前条件暂无统计报表" @selection-change="selected=$event"><el-table-column v-if="canExport" type="selection" width="45"/><el-table-column label="报表名称" min-width="340"><template #default="{row}"><el-button link class="ca-company" @click="c.open(row.id)">{{row.title}}</el-button><span class="ca-secondary">{{row.businessNo}}</span></template></el-table-column><el-table-column label="统计周期" min-width="220"><template #default="{row}">{{day(row.periodStart)}} — {{day(row.periodEnd)}}</template></el-table-column><el-table-column label="分类" width="120"><template #default="{row}"><el-tag :type="row.category==='SAFETY'?'warning':row.category==='COMPREHENSIVE'?'success':'primary'">{{row.category==='SAFETY'?'安全统计':text(row.category)}}</el-tag></template></el-table-column><el-table-column label="生成时间" width="180"><template #default="{row}">{{time(row.generatedAt)}}</template></el-table-column><el-table-column label="操作" :width="c.narrow.value?(canExport?140:90):220" fixed="right"><template #default="{row}"><el-button link type="primary" @click="c.open(row.id)">预览</el-button><el-button v-if="canExport" link type="primary" @click="notifyDownload(`${cityApi}/reports/${row.id}/export`)">导出</el-button></template></el-table-column></el-table></div><footer class="ca-foot"><span>报表按生成时间留存；预览与导出使用同一份内容。</span><el-pagination :current-page="c.page.value" :page-size="c.pageSize.value" :total="total" :page-sizes="[10,20,50]" layout="total, sizes, prev, pager, next" @current-change="c.paginate" @size-change="(v:number)=>c.paginate(1,v)"/></footer></article>
 <CityAnalyticsDrawer v-model="visible" title="报表预览" width="740px"><div v-if="detailError" class="ca-error" role="alert"><strong>报表暂时无法加载</strong><span>{{detailError}}</span><el-button @click="loadDetail">重试</el-button></div><el-skeleton v-else-if="detailLoading" :rows="15" animated/><template v-else-if="detail"><el-tag type="success">已生成</el-tag><p class="ca-note">报表编号 {{detail.businessNo}}<br/>生成时间 {{time(detail.generatedAt)}}</p><CityReportDocument :report="detail"/></template><template #footer><el-button @click="visible=false">关闭</el-button><el-button v-if="canExport&&detail" type="primary" :icon="Download" @click="notifyDownload(`${cityApi}/reports/${detail.id}/export`)">导出数据</el-button></template></CityAnalyticsDrawer>
 <el-dialog v-model="createOpen" title="生成统计报表" width="640px" class="ca-dialog" :close-on-click-modal="false" :close-on-press-escape="!saving" :show-close="!saving"><el-form label-position="top"><el-form-item label="报表名称" required><el-input v-model="form.title" maxlength="200" aria-label="报表名称"/></el-form-item><el-form-item label="报表分类"><el-select v-model="form.category" aria-label="生成报表分类"><el-option v-for="[key,label] in categories" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="周期类型"><el-select v-model="form.reportType" aria-label="生成周期类型" @change="periodChanged"><el-option v-for="[key,label] in periods" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="统计周期" required><el-date-picker v-model="form.dates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" aria-label="统计周期"/></el-form-item><el-form-item :label="form.category==='ENTERPRISE'?'指定企业（必选）':'指定企业（可选）'"><el-select v-model="form.enterpriseId" clearable filterable placeholder="全部授权企业" aria-label="报表企业"><el-option v-for="e in options.enterprises" :key="e.id" :label="e.name" :value="e.id"/></el-select></el-form-item></el-form><p class="ca-note">生成时留存数据，后续实时数据变化不会改写此报表。若包含今天，仅统计至生成时间。未提交内容自动保留。</p><div v-if="createError" class="ca-form-error" role="alert">{{createError}}</div><template #footer><el-button :disabled="saving" @click="createOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="create">生成并预览</el-button></template></el-dialog>
</section></template>
